package codex

import (
	"fmt"
	"io"
	"net/http"

	"github.com/anoosa/dar/internal/server"
	"github.com/anoosa/dar/internal/webui"
)

func (s *Service) handlePage(w http.ResponseWriter, r *http.Request) {
	user := server.GetUser(r)
	if user == nil {
		http.Redirect(w, r, "/login", http.StatusSeeOther)
		return
	}
	if err := s.renderPage(w, r, user.DisplayName); err != nil {
		http.Error(w, "Internal server error", http.StatusInternalServerError)
	}
}

func (s *Service) renderPage(w io.Writer, r *http.Request, displayName string) error {
	content, _ := webui.ExternalizeLastScript(codexHTML(s.csrf(r)), "/codex/assets/app.js")
	return webui.RenderRequest(w, r, webui.PageData{
		Title: "Codex — Dar", CurrentApp: "codex", AppBar: server.AppBarHTML(r), UserMenu: webui.UserMenuHTML(displayName),
		Sidebar: webui.BuildSidebar(webui.SidebarConfig{StateKey: "codex", AriaLabel: "Codex navigation", Items: []webui.SidebarItem{{Label: "Chats", Icon: "fa-solid fa-comments", Href: "/codex", Active: true}}, SettingsHref: "/settings"}),
		Content: content,
	})
}

func (s *Service) handleAsset(w http.ResponseWriter, r *http.Request) {
	_, script := webui.ExternalizeLastScript(codexHTML(s.csrf(r)), "/codex/assets/app.js")
	webui.ServeAppJavaScript(w, r, "app.js", script)
}

func codexHTML(csrf string) string {
	return fmt.Sprintf(`
<div class="h-full min-h-0 p-4 md:p-6">
<div id="codex-app" data-dar-shell class="focus-panel flex h-full min-h-0 overflow-hidden bg-surface">
  <aside data-dar-master-pane class="w-full shrink-0 border-r border-outline-variant flex flex-col bg-surface-container-low lg:w-72">
    <header data-dar-sidebar-toggle-host class="flex h-14 shrink-0 items-center gap-2 border-b border-outline-variant px-3"><h1 class="min-w-0 flex-1 truncate text-lg font-semibold">Chats</h1></header>
    <div class="p-3 flex gap-2"><button id="codex-new" class="flex-1 h-10 rounded-full bg-primary text-on-primary text-sm font-medium"><i class="fa-solid fa-plus mr-2"></i>New chat</button><button id="codex-settings" class="w-10 h-10 rounded-full hover:bg-surface-container-highest" title="Codex settings"><i class="fa-solid fa-gear"></i></button></div>
    <div id="codex-sessions" class="flex-1 overflow-y-auto px-2 space-y-1"></div>
  </aside>
  <section id="codex-conversation" data-dar-detail-pane class="hidden min-w-0 flex-1 flex-col bg-transparent lg:flex" aria-label="Codex conversation">
    <header class="h-14 shrink-0 border-b border-outline-variant flex items-center gap-3 bg-transparent px-4">
      <button id="codex-back" data-dar-detail-back class="h-10 w-10 rounded-full hover:bg-surface-container-high lg:hidden" aria-label="Back to chats"><i class="fa-solid fa-arrow-left"></i></button>
      <h1 id="codex-title" class="font-semibold truncate flex-1">Codex</h1>
      <select id="codex-model" class="bg-surface-container rounded-full px-3 py-2 text-sm max-w-52" aria-label="Model"></select>
      <select id="codex-effort" class="bg-surface-container rounded-full px-3 py-2 text-sm" aria-label="Reasoning effort"><option value="">Default effort</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="xhigh">Extra high</option></select>
    </header>
    <div id="codex-notice" role="status" aria-live="polite" class="hidden mx-4 mt-3 rounded-md px-4 py-3 text-sm"></div>
    <section id="codex-setup" class="hidden flex-1 overflow-y-auto p-8"><div class="max-w-xl mx-auto bg-surface-container rounded-md p-6"><h2 class="text-xl font-semibold mb-2">Connect Codex</h2><p id="codex-diagnostic" class="text-sm text-on-surface-variant mb-5"></p><button id="codex-device" class="h-11 px-5 rounded-full bg-primary text-on-primary font-medium">Sign in with ChatGPT</button><div id="codex-device-result" class="hidden mt-4 rounded-md bg-primary-container p-4 text-sm"></div><div class="my-5 flex items-center gap-3 text-xs text-on-surface-variant"><span class="h-px bg-outline-variant flex-1"></span>or API key<span class="h-px bg-outline-variant flex-1"></span></div><form id="codex-key-form" class="flex gap-2"><input id="codex-key" type="password" autocomplete="off" placeholder="OpenAI API key" class="flex-1 h-11 rounded-full bg-surface px-4"><button class="h-11 px-5 rounded-full border border-primary text-primary">Connect</button></form><p class="mt-3 text-xs text-on-surface-variant">Codex may store the API key as plaintext inside this user's protected server-side CODEX_HOME.</p></div></section>
    <section id="codex-empty" class="flex-1 flex items-center justify-center text-center p-8"><div><i class="fa-solid fa-terminal text-5xl text-primary mb-4"></i><h2 class="text-xl font-semibold">Your Dar assistant</h2><p class="text-on-surface-variant mt-2">Start a chat to work with your files, calendar, contacts, tasks, notes, news, and email.</p></div></section>
    <section id="codex-chat" class="hidden min-h-0 flex-1 flex-col"><div id="codex-messages" class="flex-1 overflow-y-auto p-5 space-y-5"></div><div id="codex-attachments" class="hidden px-5 py-2 flex gap-2 flex-wrap"></div><div class="border-t border-outline-variant p-4"><div class="max-w-4xl mx-auto rounded-3xl bg-surface-container p-2 flex items-end gap-2"><button id="codex-upload" class="w-10 h-10 rounded-full hover:bg-surface-container-highest" title="Upload image"><i class="fa-solid fa-image"></i></button><button id="codex-picker" class="w-10 h-10 rounded-full hover:bg-surface-container-highest" title="Choose from Files"><i class="fa-solid fa-paperclip"></i></button><input id="codex-file" type="file" accept="image/*" class="hidden"><textarea id="codex-input" rows="1" placeholder="Ask Codex..." class="min-h-10 max-h-40 flex-1 resize-none bg-transparent border-0 outline-none px-2 py-2"></textarea><button id="codex-stop" class="hidden w-10 h-10 rounded-full bg-error-container text-error" title="Stop"><i class="fa-solid fa-stop"></i></button><button id="codex-send" class="w-10 h-10 rounded-full bg-primary text-on-primary" title="Send"><i class="fa-solid fa-arrow-up"></i></button></div><p class="text-xs text-center text-on-surface-variant mt-2">Codex can make mistakes. Confirm important changes.</p></div></section>
  </section>
</div>
</div>
<dialog id="codex-settings-dialog" class="rounded-md bg-surface text-on-surface p-0 shadow-xl backdrop:bg-scrim/30"><form method="dialog" class="w-[min(32rem,90vw)]"><header class="p-5 border-b border-outline-variant flex"><h2 class="font-semibold flex-1">Codex settings</h2><button class="w-8 h-8 rounded-full">✕</button></header><div class="p-5 space-y-5"><label class="block"><span class="text-sm font-medium">Action approval</span><select id="codex-approval-mode" class="mt-2 w-full h-11 rounded-md bg-surface-container px-3"><option value="confirm">Confirm every write</option><option value="automatic">Automatic safe writes</option></select><span class="block text-xs text-on-surface-variant mt-1">Sends, shares, subscription changes, and deletes always require confirmation.</span></label><label class="block"><span class="text-sm font-medium">Web search</span><select id="codex-web-search" class="mt-2 w-full h-11 rounded-md bg-surface-container px-3"><option value="disabled">Disabled</option><option value="cached">Cached/indexed</option><option value="live">Live</option></select><span class="block text-xs text-on-surface-variant mt-1">Live search can expose the conversation to prompt-injection risks.</span></label><button id="codex-save-settings" value="cancel" type="button" class="h-11 px-5 rounded-full bg-primary text-on-primary">Save</button><button id="codex-logout" value="cancel" type="button" class="h-11 px-5 rounded-full text-error">Disconnect Codex</button></div></form></dialog>
<script src="/files/assets/picker.js"></script>
<script>
(()=>{'use strict';
const csrf=%q, state={status:null,sessions:[],session:null,source:null,attachments:[],streaming:false,loading:false,assistant:null};
const $=id=>document.getElementById(id), api=async(path,opts={})=>{opts.headers=Object.assign({'Accept':'application/json'},opts.headers||{});if(opts.method&&opts.method!=='GET')opts.headers['X-Dar-CSRF-Token']=csrf;const r=await fetch('/api/codex'+path,opts);if(r.status===204)return null;const text=await r.text();let data;try{data=JSON.parse(text)}catch{data={error:text}}if(!r.ok)throw new Error(data.error||'Request failed');return data};
function show(id,on=true){$(id).classList.toggle('hidden',!on)}
function notice(message='',kind='error'){const box=$('codex-notice');box.textContent=message;box.className='mx-4 mt-3 rounded-md px-4 py-3 text-sm '+(kind==='error'?'bg-error-container text-error':'bg-primary-container text-on-primary-container');show('codex-notice',Boolean(message))}
function closeSource(){if(state.source){state.source.close();state.source=null}}
function setLoading(on){state.loading=on;$('codex-new').disabled=on;$('codex-settings').disabled=on;renderSessions()}
function textOf(item){if(typeof item.text==='string')return item.text;if(typeof item.message==='string')return item.message;if(typeof item.content==='string')return item.content;if(Array.isArray(item.content))return item.content.map(x=>x.text||x.content||'').join('');return ''}
function markdown(root,text){root.textContent='';let code=null;const fence=String.fromCharCode(96,96,96);for(const line of String(text||'').split('\n')){if(line.startsWith(fence)){if(code){code=null}else{const pre=document.createElement('pre');pre.className='overflow-x-auto rounded-md bg-surface-container-highest p-3 text-xs my-2';code=document.createElement('code');pre.appendChild(code);root.appendChild(pre)}continue}if(code){code.textContent+=line+'\n';continue}const p=document.createElement(line.startsWith('- ')?'li':'p');p.className='whitespace-pre-wrap my-1';p.textContent=line.startsWith('- ')?line.slice(2):line;root.appendChild(p)}}
function bubble(role,text){const row=document.createElement('div');row.className='flex '+(role==='user'?'justify-end':'justify-start');const card=document.createElement('div');card.className=(role==='user'?'bg-primary-container':'bg-surface-container')+' rounded-2xl px-4 py-3 max-w-[85%%] text-sm';const content=document.createElement('div');markdown(content,text);card.appendChild(content);row.appendChild(card);$('codex-messages').appendChild(row);$('codex-messages').scrollTop=$('codex-messages').scrollHeight;return content}
function renderSessions(){const root=$('codex-sessions');root.textContent='';for(const s of state.sessions){const row=document.createElement('div');row.className='group flex items-center rounded-md '+(state.session?.id===s.id?'bg-secondary-container':'hover:bg-surface-container-highest');const b=document.createElement('button');b.disabled=state.loading;b.className='min-w-0 flex-1 text-left px-3 py-2 text-sm truncate disabled:opacity-50';b.textContent=s.title||'New chat';b.onclick=()=>openSession(s.id);const archive=document.createElement('button');archive.disabled=state.loading;archive.className='w-8 h-8 text-on-surface-variant disabled:opacity-50';archive.setAttribute('aria-label','Archive '+(s.title||'New chat'));archive.innerHTML='<i class="fa-solid fa-box-archive"></i>';archive.onclick=e=>{e.stopPropagation();archiveSession(s.id)};row.append(b,archive);root.appendChild(row)}}
async function loadSessions(){const d=await api('/sessions');state.sessions=d.sessions||[];renderSessions()}
function renderHistory(data){$('codex-messages').textContent='';const thread=data?.thread?.thread||data?.thread||{};for(const turn of thread.turns||[]){for(const item of turn.items||[]){const type=String(item.type||'').toLowerCase();const t=textOf(item);if(!t)continue;if(type.includes('user'))bubble('user',t);else if(type.includes('agent')||type.includes('assistant'))bubble('assistant',t)}}}
function connectEvents(id,after=0){closeSource();const source=new EventSource('/api/codex/sessions/'+id+'/events?after='+encodeURIComponent(after));state.source=source;for(const type of ['message.delta','turn.started','turn.completed','turn.interrupted','tool.started','tool.completed','approval.required','error','resync','session.renamed'])source.addEventListener(type,e=>{if(source!==state.source)return;try{onEvent(type,JSON.parse(e.data||'{}'))}catch(err){notice(err.message)}});source.onerror=()=>{if(source===state.source&&source.readyState===EventSource.CLOSED)notice('The live Codex connection closed. Reopen the chat to reconnect.')}}
function showConversation(){show('codex-setup',false);show('codex-empty',false);show('codex-chat',true);$('codex-chat').classList.add('flex');DarUI.shell.openDetail($('codex-conversation'),{master:$('codex-sessions').parentElement})}
function showEmptyState(){closeSource();state.session=null;state.assistant=null;setStreaming(false);$('codex-title').textContent='Codex';$('codex-messages').textContent='';$('codex-input').value='';state.attachments=[];renderAttachments();show('codex-chat',false);$('codex-chat').classList.remove('flex');show('codex-empty',true);renderSessions()}
function createDraft(){if(state.loading)return;closeSource();state.session=null;state.assistant=null;setStreaming(false);notice();$('codex-title').textContent='New chat';$('codex-messages').textContent='';$('codex-input').value='';state.attachments=[];renderAttachments();if(DarUI.shell.isCompact()&&!history.state?.darDetail)history.pushState({darDetail:'codex'},'','#new');showConversation();renderSessions();$('codex-input').focus()}
async function openSession(id){if(state.loading)return;setLoading(true);notice('Loading chat…','info');closeSource();try{const data=await api('/sessions/'+id);state.session=data.session;state.sessions=state.sessions.map(s=>s.id===id?data.session:s);$('codex-title').textContent=data.session.title||'New chat';$('codex-model').value=data.session.model||'';$('codex-effort').value=data.session.reasoning_effort||'';state.assistant=null;renderHistory(data);if(DarUI.shell.isCompact()){if(history.state?.darDetail==='codex')history.replaceState({...history.state,darDetail:'codex'},'','#session-'+encodeURIComponent(id));else history.pushState({darDetail:'codex'},'','#session-'+encodeURIComponent(id))}showConversation();connectEvents(id,data.event_cursor||0);notice()}catch(e){notice(e.message);await loadSessions().catch(()=>{});showEmptyState()}finally{setLoading(false)}}
function clearApprovalCards(){document.querySelectorAll('[data-codex-approval]').forEach(node=>node.remove())}
function onEvent(type,d){if(type==='message.delta'){if(!state.assistant)state.assistant=bubble('assistant','');state.assistant.dataset.text=(state.assistant.dataset.text||'')+(d.delta||'');markdown(state.assistant,state.assistant.dataset.text)}else if(type==='turn.started'){setStreaming(true)}else if(type==='turn.completed'){clearApprovalCards();setStreaming(false);state.assistant=null;loadSessions().catch(e=>notice(e.message))}else if(type==='turn.interrupted'){clearApprovalCards();setStreaming(false);state.assistant=null;notice('The current response was stopped.','info')}else if(type==='approval.required'){approvalCard(d)}else if(type==='error'){setStreaming(false);notice(d.message||'Codex failed')}else if(type==='resync'&&state.session){openSession(state.session.id)}else if(type==='session.renamed'){loadSessions().catch(e=>notice(e.message))}}
function approvalCard(d){const row=document.createElement('div');row.dataset.codexApproval='true';row.className='rounded-md border border-outline-variant bg-surface-container p-4 text-sm';const title=document.createElement('strong');title.textContent='Approve '+d.namespace+'.'+d.tool+'?';const pre=document.createElement('pre');pre.className='text-xs whitespace-pre-wrap mt-2';pre.textContent=JSON.stringify(d.arguments||{},null,2);const yes=document.createElement('button');yes.className='mt-3 mr-2 px-4 py-2 rounded-full bg-primary text-on-primary';yes.textContent='Approve';const no=document.createElement('button');no.className='mt-3 px-4 py-2 rounded-full text-error';no.textContent='Deny';yes.onclick=()=>decide(d.call_id,'approve',row);no.onclick=()=>decide(d.call_id,'deny',row);row.append(title,pre,yes,no);$('codex-messages').appendChild(row)}
async function decide(id,decision,row){try{await api('/approvals/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision})});row.remove()}catch(e){notice(e.message)}}
function setStreaming(on){state.streaming=on;show('codex-stop',on);show('codex-send',!on);$('codex-input').disabled=on;$('codex-send').disabled=on;$('codex-model').disabled=on;$('codex-effort').disabled=on}
async function send(){if(state.streaming||state.loading)return;const input=$('codex-input'),text=input.value.trim(),attachments=[...state.attachments];if(!text&&!attachments.length)return;input.value='';const optimistic=bubble('user',text||'(attachments)');state.assistant=null;setStreaming(true);notice();const body=JSON.stringify({text,model:$('codex-model').value,reasoningEffort:$('codex-effort').value,attachments:attachments.map(x=>x.id)});try{if(state.session){await api('/sessions/'+state.session.id+'/turns',{method:'POST',headers:{'Content-Type':'application/json'},body})}else{const data=await api('/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body});state.session=data.session;state.sessions.unshift(data.session);$('codex-title').textContent=data.session.title||'New chat';renderSessions();connectEvents(data.session.id)}state.attachments=[];renderAttachments()}catch(e){optimistic.parentElement.parentElement.remove();input.value=text;state.attachments=attachments;renderAttachments();setStreaming(false);notice(e.message);input.focus()}}
async function archiveSession(id){if(state.loading)return;setLoading(true);notice();try{await api('/sessions/'+id+'/archive',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({archived:true})});if(state.session?.id===id)showEmptyState();await loadSessions();notice('Chat archived.','info')}catch(e){notice(e.message)}finally{setLoading(false)}}
async function loadModels(){try{const d=await api('/models'),models=d.data||d.models||[];$('codex-model').innerHTML='<option value="">Default model</option>';for(const m of models){const o=document.createElement('option');o.value=m.id||m.model||m.slug;o.textContent=m.displayName||m.name||o.value;$('codex-model').appendChild(o)}}catch{ $('codex-model').innerHTML='<option value="">Default model</option>'}}
async function loadPrefs(){const p=await api('/preferences');$('codex-approval-mode').value=p.approval_mode;$('codex-web-search').value=p.web_search_mode}
async function setup(){const st=await api('/status');state.status=st;show('codex-setup',!st.available||!st.authenticated);show('codex-empty',st.available&&st.authenticated&&!state.session);$('codex-diagnostic').textContent=!st.available?(st.error||'Codex is unavailable.'):(st.auth_error||'Sign in separately for this Dar user.');if(st.available&&st.authenticated){await Promise.all([loadSessions(),loadModels(),loadPrefs()]);if(location.hash.startsWith('#session-')){if(DarUI.shell.isCompact())history.replaceState({darDetail:'codex',darDirect:'codex'},'',location.href);await openSession(decodeURIComponent(location.hash.slice(9)))}}}
function renderAttachments(){const root=$('codex-attachments');root.textContent='';show('codex-attachments',state.attachments.length>0);for(const a of state.attachments){const chip=document.createElement('button');chip.className='px-3 py-1 rounded-full bg-secondary-container text-xs';chip.textContent=a.name+' ×';chip.onclick=()=>{state.attachments=state.attachments.filter(x=>x.id!==a.id);renderAttachments()};root.appendChild(chip)}}
$('codex-new').onclick=createDraft;$('codex-send').onclick=send;$('codex-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};$('codex-stop').onclick=async()=>{if(!state.session)return;notice('Stopping the current response…','info');try{await api('/sessions/'+state.session.id+'/interrupt',{method:'POST'})}catch(e){notice(e.message)}};$('codex-settings').onclick=async()=>{try{await loadPrefs();$('codex-settings-dialog').showModal()}catch(e){notice(e.message)}};$('codex-save-settings').onclick=async()=>{try{await api('/preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({approval_mode:$('codex-approval-mode').value,web_search_mode:$('codex-web-search').value})});$('codex-settings-dialog').close();notice('Codex settings saved.','info')}catch(e){notice(e.message)}};$('codex-logout').onclick=async()=>{try{closeSource();await api('/logout',{method:'POST'});location.reload()}catch(e){notice(e.message)}};
$('codex-back').onclick=()=>{if(DarUI.shell.isCompact()&&history.state?.darDirect==='codex'){history.replaceState({},'',location.pathname);DarUI.shell.closeDetail($('codex-conversation'),{master:$('codex-sessions').parentElement})}else if(DarUI.shell.isCompact()&&history.state?.darDetail==='codex')history.back();else DarUI.shell.closeDetail($('codex-conversation'),{master:$('codex-sessions').parentElement})};window.addEventListener('popstate',()=>{if(DarUI.shell.isCompact()&&!history.state?.darDetail)DarUI.shell.closeDetail($('codex-conversation'),{master:$('codex-sessions').parentElement})});
$('codex-device').onclick=async()=>{try{const d=await api('/login/device',{method:'POST'}),box=$('codex-device-result');box.textContent='Open '+d.verificationUrl+' and enter code '+d.userCode;show('codex-device-result',true);setTimeout(()=>location.reload(),15000)}catch(e){$('codex-diagnostic').textContent=e.message}};$('codex-key-form').onsubmit=async e=>{e.preventDefault();try{await api('/login/api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({api_key:$('codex-key').value})});location.reload()}catch(err){$('codex-diagnostic').textContent=err.message}};
$('codex-upload').onclick=()=>$('codex-file').click();$('codex-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const form=new FormData();form.append('file',f);const a=await api('/attachments/upload',{method:'POST',body:form});state.attachments.push(a);renderAttachments();notice()}catch(err){notice(err.message)}finally{e.target.value=''}};$('codex-picker').onclick=async()=>{try{const files=await DarFilePicker.open({selection:'files',multiple:true,title:'Add Dar files'});if(!files.length)return;const d=await api('/attachments/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:files.map(f=>f.path)})});state.attachments.push(...d.attachments);renderAttachments();notice()}catch(e){notice(e.message)}};
setup().catch(e=>{$('codex-diagnostic').textContent=e.message;show('codex-setup',true)});
})();
</script>`, csrf)
}
